# Flood fill from OUTSIDE to find exterior 0s
# Then non-exterior 0s become 3

def flood_from_outside(grid):
    rows = len(grid)
    cols = len(grid[0])

    exterior = [[False] * cols for _ in range(rows)]
    queue = collections.deque()

    # Add all edge 0s as starting points for flood
    for r in range(rows):
        for c in [0, cols-1]:
            if grid[r][c] == 0:
                exterior[r][c] = True
                queue.append((r, c))
    for r in [0, rows-1]:
        for c in range(1, cols-1):
            if grid[r][c] == 0:
                exterior[r][c] = True
                queue.append((r, c))

    # Flood fill 0s reachable from edges
    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if not exterior[nr][nc] and grid[nr][nc] == 0:
                    exterior[nr][nc] = True
                    queue.append((nr, nc))

    return exterior

